import MasterData from "./MasterData.js";
import { Support } from "../../LAMP/RenderModule/modules/library.js";
import { isLocal, loadApi } from "../../core.js";
import { API_URL } from "../../obi.config.js";

const placeholderFile = {
    filebits: "",
    filename: "loading...",
    options: {
        type: "image/png",
        endings: "transparent",
        lastModified: 1748439916846,
        path: "",
        size: 404271
    },
    id: 0,
    placeholder: true,
};

export const enumStatiMessaggio = Object.freeze({
    Generato: 1,
    Inviato: 2,
    Sospeso: 3,
    Modificato: 4,
    Cancellato: 5,
    Errore: 6
});

export default class Message extends MasterData {

    /**Riferimento alla chat*/
    codice = "";
    /**Lista dei tag personalizzati del messaggio*/
    tags = "";
    /**Id del file in archivio allegato*/
    idAllegato = 0;
    /**Id del messaggio di riferimento al quale il presente fa da risposta*/
    idRisposta = 0;
    /**Stato di invio del messaggio*/
    idStato = 1;

    //#region Render
    /**Link all'immagine del profilo utente*/
    profilo = null;
    /**Documenti allegati del messaggio*/
    attachments = [];
    /**Contenuto del messaggio riferito all'idRisposta*/
    repliedMessage = null;
    /**Indica se il messaggio è un separatore di data*/
    isSeparator = false;
    /**Tipo di raggruppamento grafico del messaggio*/
    group = "single";
    /**Lista degli attributi del messaggio */
    attributi = [];
    //#endregion


    get hasAttachments() { return this.attachments.length > 0 || !!this.idAllegato; }
    get time() { return ("0" + this.timeStamp.getHours()).padRight(2) + ":" + ("0" + this.timeStamp.getMinutes()).padRight(2); }
    get edited() { return this.idStato === 4; }
    get stato() {
        const entry = Object.entries(enumStatiMessaggio).find(([key, value]) => value === this.idStato);
        return entry ? entry[0] : "";
    }
    get unsent() {
        return ![enumStatiMessaggio.Inviato, enumStatiMessaggio.Modificato, enumStatiMessaggio.Cancellato].includes(this.idStato);
    }

    constructor(init) {

        super(init);
        if (!this.id) this.id = Support.uniqueID();
        if (!this.timeStamp) this.timeStamp = new Date();

        if (init != null) {
            const getterNames = Object.getOwnPropertyNames(Object.getPrototypeOf(this))
                .filter(name => typeof Object.getOwnPropertyDescriptor(Object.getPrototypeOf(this), name)?.get === "function");

            for (const [key, value] of Object.entries(init)) {
                if (!getterNames.includes(key)) {
                    this[key] = value;
                }
            }
        }

        if (this.idAllegato && this.attachments.length === 0) this.attachments.push({ ...placeholderFile, id: this.idAllegato });
        this.attributi = init?.attributi ?? (this.tags ? JSON.parse(this.tags).map(e => new Attribute(e)) : []);
    }

    toDBModel() {
        return {
            id: typeof this.id === "string" ? 0 : this.id,
            codice: this.codice,
            nome: this.nome,
            note: this.note,
            timeStamp: this.timeStamp,
            insertTime: this.insertTime ? this.insertTime : null,
            idOwner: this.idOwner,
            idLastUser: this.idLastUser,
            idStato: this.idStato,
            idRisposta: this.idRisposta,
            idAllegato: this.idAllegato,
            tags: JSON.stringify(this.attributi),
        };
    }

    toJson() {
        return {
            codice: this.codice,
            id: this.id,
            nome: this.nome,
            note: this.note,
            timeStamp: this.timeStamp,
            insertTime: this.insertTime,
            idOwner: this.idOwner,
            idLastUser: this.idLastUser,
            idStato: this.idStato,
            idRisposta: this.idRisposta,
            idAllegato: this.idAllegato,
            tags: JSON.stringify(this.attributi),
            profilo: this.profilo,
            attachments: this.attachments,
        };
    }

    async loadAttachments() {
        try {
            if (isLocal()) return; // load only in local mode
            const api = await loadApi(`${API_URL}/OBIArchivio/Scripts/services/documenti.service.js`);
            const service = new api();
            this.attachments = await Promise.all(
                this.attachments.map(async (f) => {
                    if (!f.documento.placeholder) return f; // return original if not placeholder
                    const doc = await service.getDocumento(f.documento.id);
                    return { ...f, documento: doc };
                }));
        } catch (err) {
            console.error(err);
        }
    }

    static parseJson(json) {
        return new Messaggio(JSON.parse(json));
    }

    static instanceAttribute(init) {
        return new Attribute(init);
    }
}

class Attribute {

    label = "";
    icona = "";
    color = "";
    title = "";
    event = "";
    variant = "";

    script = "";

    get action() { return new Function(this.script); }

    constructor(init = null) {
        if (init) Object.assign(this, init);
    }
}